const traceCases=__MEMORY_CASES__;let traceCase=null,traceIndex=0;
function traceStep(){if(!traceCase||traceIndex>=traceCase.trace.length)return;const event=traceCase.trace[traceIndex++];document.getElementById('traceOutput').textContent='执行者：'+event.owner+'
动作：'+event.action+'
账本：'+event.used_mib+' MiB
真实分配累计：'+event.driver_alloc_calls+'
真实释放累计：'+event.driver_free_calls+'
调度器 RPC：'+event.scheduler_rpc+(event.result?'
返回：'+event.result:'')+(event.failure_origin?'
归因：'+event.failure_origin:'');document.getElementById('traceProgress').textContent=traceCase.title+' · '+traceIndex+'/'+traceCase.trace.length+'；教学轨迹';document.getElementById('traceNext').disabled=traceIndex>=traceCase.trace.length;}
document.querySelectorAll('[data-trace]').forEach(button=>button.onclick=()=>{traceCase=traceCases[button.dataset.trace];traceIndex=0;document.getElementById('traceOutput').textContent='已选择：'+traceCase.title+'。先预测第一步是谁执行，再点下一步。';document.getElementById('traceProgress').textContent='未开始';document.getElementById('traceNext').disabled=false;});document.getElementById('traceNext').onclick=traceStep;
